from research_helpers import *
a=ev('https://mendus.com/what-we-do/','Current issuer identifies vididencel immunotherapy and DCOne immune-cell expansion technology available for licensing; expanded-access policy also names ilixadencel.')
b=ev('https://mendus.com/news/mendus-ab-year-end-report-2024/','Issuer states planned ilixadencel REGOMUNE trial could not proceed because external funding terminated; does not declare entire programme discontinued.')
c=ev('https://mendus.com/sv/news/dcp-001-blir-vididencel/','Issuer explicitly identifies vididencel as INN of DCP001; same programme, not separate product.')
d=ev('https://mendus.com/investors/press-releases/','September16 2026 issuer announces DIVA initiation, updating older forecasts. July2026 VITAL-CML first-stage enrollment and planned VITAL-TFR2 distinguish trials from product identities.')
cs=[company('MENDUS AB',[p('Vididencel','Investigational allogeneic leukemia-cell-derived immunotherapy for myeloid blood cancers, also studied in ovarian cancer.',a,'development',aliases=['DCP-001'],evidence=[a,c,d]),p('Ilixadencel','Investigational intratumoral immune-priming cell therapy; planned REGOMUNE participation lost external funding, overall current programme activity unconfirmed.',b,'unknown',evidence=[a,b]),p('DCOne platform','Immune-cell expansion technology for NK cells and tumor-infiltrating lymphocytes, available for licensing.',a,'commercial',typ='technology',sub='research_tools')],[a,b,c,d],'Current two cell-therapy identities and DCOne technology reviewed; trial names are not separate products. Ilixadencel current activity and legacy Immunicum platform/candidate histories remain to verify, as do full indication-stage contexts.')]
e=ev('https://www.camurus.com/files/Presentations/camurus-company-presentation-may-2026.pdf','Issuer May2026 portfolio identifies marketed Buvidal/Brixadi weekly/monthly depots, Oczyesa, FluidCrystal technology, CAM2056/4072/4071/2038/2029/2043 and other clinical programmes CAM2032/2047. Same formulation across indications is one product.')
f=ev('https://www.camurus.com/media/press-releases/2026/camurus-nda-resubmission-for-cam2029-in-acromegaly-accepted-for-review-by-the-us-fda/','July17 2026 issuer says CAM2029/Oczyesa approved EU/UK, US resubmission under review with December18 2026 target. Oclaiz proposed US brand not approved US medicine.')
g=ev('https://www.camurus.com/files/Main/13456/2807909/interim-report-camurus-q1-2019.pdf','Historical issuer pipeline distinguishes weekly/monthly buprenorphine, CAM4072 weekly setmelanotide, CAM2048/2058 postoperative-pain/PONV project and episil oral liquid; legacy current status not inferred.')
ps=[]
for interval in ['weekly','monthly']:
 ps.append(p('Buvidal '+interval,'Long-acting subcutaneous buprenorphine depot '+interval+' formulation for opioid dependence, marketed as Brixadi '+interval+' in US.',e,'commercial',typ='product',aliases=['Brixadi '+interval],attributes={'development_code':'CAM2038','dosing_interval':interval,'active_ingredient':'buprenorphine'},evidence=[e,g]))
ps.append(p('Oczyesa','Monthly subcutaneous extended-release octreotide formulation, commercial in Europe for acromegaly; US Oclaiz application under review, also studied in GEP-NET and polycystic liver disease.',f,'commercial',typ='product',aliases=['CAM2029','Oclaiz'],attributes={'active_ingredient':'octreotide','US_regulatory_status':'under_review','US_target_action_date':'2026-12-18'},evidence=[e,f]))
ps.append(p('FluidCrystal','Long-acting release formulation technology for injectable drug depots.',e,'commercial',typ='technology'))
for name,desc in [('CAM2056','Investigational monthly semaglutide formulation for metabolic diseases, distinct from weekly third-party semaglutide brands.'),('CAM4072','Investigational extended-release weekly setmelanotide formulation for genetic obesity disorders, partnered with Rhythm; not daily Imcivree.'),('CAM4071','Investigational depot programme for endocrine disorders.'),('CAM2032','Investigational depot programme for prostate cancer.'),('CAM2043','Investigational long-acting treprostinil programme studied in Raynaud phenomenon and pulmonary arterial hypertension.'),('CAM2047','Investigational programme for chemotherapy-induced nausea and vomiting.')]:ps.append(p(name,desc,e,'development',evidence=[e,g]))
ps.append(p('episil oral liquid','Historical oral liquid medical-device formulation for oral mucositis; current rights and availability not established.',g,'unknown',typ='product'))
cs.append(company('Camurus AB',ps,[e,f,g],'Two dosing-interval buprenorphine products, one octreotide formulation, FluidCrystal, six named investigational programmes and historical episil reviewed. Regional brand names and new indications do not create duplicate products. Oclaiz remains US application, December2026 target not completed approval. Legacy CAM2048/2058 identity/current rights, proprietary platform variants, partner-specific molecules, strengths and full indication-stage contexts remain to research.'))
(out/'batch-0117.json').write_text(json.dumps({'companies':cs},indent=2));print(sum(len(c['products']) for c in cs))
